%Problema 63.2. Determinati toate radacinile ecuatiei %		x^4-x^3+5/4*x^2-x+1/4%cu metoda lui Newton. Atentie, ecuatia are o radacina reala dubla si doua %complexe.%creare obiecte simbolicesyms f;syms x;%ecuatiaf = x^4-x^3+5/4*x^2-x+1/4;%setam solutia posibila ca fiind un divizor al termenului liberxPosibil = 1/4;%nmax - numarul maxim de iteratii nmax=50;%er - eroarea relativa er=0;%ea - eroarea absolutaea=1e-5;fprintf('Radacinile ecuatiei x^4-x^3+5/4*x^2-x+1/4=0 calculate cu metoda lui Newton: \n');radacini = ecuatie(f,xPosibil,ea,er,nmax);n = length(radacini);for i=1:n    fprintf('Radacina %d este : %s\n',i,num2str(radacini(i)));end